parameters.jsCode:
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const inputData = $input.first().json;

const clientes = inputData.body?.clientes || inputData.clientes || [];
const investimentos = inputData.investimentos || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const resultados = clientes.map(cliente => {
  const saldoNum = parseBRL(cliente.saldo);
  const perfil = cliente.perfil || "Conservador";

  // Filtra opções compatíveis com o perfil e dentro do saldo disponível
  const elegiveis = investimentos.filter(inv => 
    inv.perfil.toLowerCase() === perfil.toLowerCase() && inv.minimo <= saldoNum
  );

  // Seleciona a opção com maior valor mínimo acessível dentro dos elegíveis
  const recomendacao = elegiveis.length > 0 
    ? elegiveis.reduce((prev, curr) => (curr.minimo > prev.minimo ? curr : prev), elegiveis[0])
    : null;

  const motivo = recomendacao ? "saldo_ok" : "sem_opcao_no_saldo";

  // Formatação das mensagens estáticas de variação
  const produtoNome = recomendacao ? recomendacao.produto : "Renda Fixa";
  const produtoMinimo = recomendacao ? `R$ ${recomendacao.minimo.toLocaleString('pt-BR')},00` : "R$ 0,00";
  const rentabilidade = recomendacao ? recomendacao.rentabilidade : "N/A";

  const mensagens = recomendacao ? [
    `Olá ${cliente.nome}! Pelo seu perfil (${perfil}), uma boa opção é **${produtoNome}** (mínimo ${produtoMinimo}). Com seu saldo atual (${cliente.saldo}), você já consegue investir. Rentabilidade: ${rentabilidade}.`,
    `Oi ${cliente.nome}! Recomendação para perfil ${perfil}: **${produtoNome}** (mínimo ${produtoMinimo}). Seu saldo (${cliente.saldo}) já atende o mínimo. Rentabilidade: ${rentabilidade}.`,
    `${cliente.nome}, indo direto ao ponto: para o perfil ${perfil}, **${produtoNome}** (mínimo ${produtoMinimo}). Você tem ${cliente.saldo}, então dá pra aplicar. Rentabilidade: ${rentabilidade}.`
  ] : [
    `Olá ${cliente.nome}! No momento não encontramos opções de investimento disponíveis para o seu saldo atual (${cliente.saldo}).`
  ];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNum,
    recomendacao: recomendacao,
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: mensagens[0]
  };
});

return [{
  json: {
    ok: true,
    total_clientes: clientes.length,
    total_investimentos: investimentos.length,
    resultados: resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

