const items = $input.all();

// Tenta resgatar os dados do nó "Code in JavaScript2" para associar o e-mail e métricas por índice
let prevItems = [];
try {
  prevItems = $items("Code in JavaScript2");
} catch (e) {
  // Caso o nome do nó seja diferente ou esteja encadeado direto
}

return items.map((item, i) => {
  // Resgata os metadados do cliente do nó anterior
  const j = prevItems[i]?.json || item.json || {};

  // Extrai a string de texto retornada pelo modelo LLM
  const rawText = item.json?.content?.parts?.[0]?.text || item.json?.text || "";

  // Trata e limpa a string para converter em objeto JSON válido
  let parsed = {};
  if (rawText) {
    let cleaned = rawText.trim()
      .replace(/^```(?:json)?\s*/i, '') // Remove a abertura ```json se houver
      .replace(/\s*```$/, '');           // Remove o fechamento ``` se houver

    try {
      parsed = JSON.parse(cleaned);
    } catch (err) {
      // Fallback: tenta localizar o primeiro { e o último } caso haja texto extra
      const start = cleaned.indexOf('{');
      const end = cleaned.lastIndexOf('}');
      if (start !== -1 && end > start) {
        try {
          parsed = JSON.parse(cleaned.substring(start, end + 1));
        } catch (e2) {
          parsed = {};
        }
      }
    }
  }

  // Define o e-mail de destino
  const toEmail = j.email_to || j.email || "";

  return {
    json: {
      ok: true,
      to: toEmail,
      subject: parsed.subject || "",
      text_body: parsed.text_body || "",
      html_body: parsed.html_body || "",

      // (opcional) mantendo os campos úteis para debug/aula
      meta: {
        nome: j.nome || "",
        perfil: j.perfil || "",
        produto: j.recomendacao?.produto || "",
        minimo: j.recomendacao?.minimo || 0,
        rentabilidade: j.recomendacao?.rentabilidade || "",
        motivo: j.motivo || ""
      }
    }
  };
});
